const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const number = input[0];
const m = Number(input[1]);

const digit = new Array(26);
const groups = ['abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz'];

for (let i = 0; i < groups.length; i++) {
  for (const letter of groups[i]) {
    digit[letter.charCodeAt(0) - 97] = String(i + 2);
  }
}

let count = 0;

for (let i = 0; i < m; i++) {
  const word = input[i + 2];
  if (word.length !== number.length) continue;

  let matches = true;
  for (let j = 0; j < word.length; j++) {
    if (digit[word.charCodeAt(j) - 97] !== number[j]) {
      matches = false;
      break;
    }
  }

  if (matches) count++;
}

console.log(count);
